// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }
    function testFuzz_property(address actor, uint128 a1, uint128 a2) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(a1 > 0 && a2 > 0 && uint256(a1) + uint256(a2) >= uint256(a1));
        vm.deal(actor, uint256(a1) + uint256(a2));
        vm.prank(actor);
        c.Put{value: a1}(0);
        vm.warp(block.timestamp + 1);
        vm.prank(actor);
        c.Put{value: a2}(0);
        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == uint256(a1) + uint256(a2));
    }
}
